-- Give the seeded briefs real variety and voice. The earlier seed appended ONE
-- identical boilerplate paragraph to every brief AND reused the same four tags
-- ("On camera / Captions / One revision / Human only") everywhere, so both the
-- copy and the pills read like one robot wrote them. This rewrites each brief in
-- a DISTINCT brand voice with varied titles, formats, budgets, tone AND a varied,
-- relevant tag mix — matched on the old title so the Abuja/single-creator variety
-- from 20261030140000 is preserved (this sets title/description/format/budget/
-- tags only, never location or slots). Additive + idempotent; Dream Intrepid only.

do $$
declare
  brand uuid;
  item jsonb;
begin
  select id into brand from public.brand_profiles
  where company_name = 'Dream Intrepid Ltd.' order by created_at limit 1;
  if brand is null then
    raise notice 'Dream Intrepid Ltd. not found; skipping brief voice rewrite';
    return;
  end if;

  for item in select * from jsonb_array_elements($b$[
    {"old":"Skincare routine video for a Nigerian brand","title":"We want the 2-step, not the 10-step — skincare that fits a real morning","desc":"Here's the truth: most people won't do a 10-step routine, and we're done pretending they will. Film your actual morning — rushing, half-asleep, whatever it is — and show where our two products slot in. One honest line about what your skin was doing before. Harsh bathroom light is fine; we'd rather that than a ring-lit lie.","format":"30–45s vertical, shot on your phone","budget":28000,"tags":["On camera","Product ships","Natural light","Human only"]},
    {"old":"Fashion try-on video, Lagos preferred","title":"One look, one reason — a try-on, not a fashion show","desc":"Don't haul. Pick the single piece you'd actually text a friend about, put it on, and move in it — stairs, a spin, sitting down. Tell us the one reason it's worth the money in your own words. Lagos light, your mirror, no studio.","format":"20–35s vertical try-on","budget":32000,"tags":["On camera","Product ships","Move in it","Human only"]},
    {"old":"Home cooking video with a product in the recipe","title":"Cook the thing you'd cook anyway (just let our spice earn its spot)","desc":"We're a small kitchen brand and we're allergic to fake cooking content. Make a dish you genuinely make — jollof, stew, a quick breakfast — and use the product where it belongs, not where a script says. We want the real kitchen: the gas cooker, the noise, your hands. One taste reaction at the end, honest.","format":"45–60s, kitchen-real","budget":24000,"tags":["On camera","Product ships","Kitchen-real","Human only"]},
    {"old":"Fitness routine video","title":"A 30-second move someone can copy before they talk themselves out of it","desc":"No transformation arc, no gym-bro voice. Give us one move or mini-routine a beginner can actually do at home, use the product once the way you really would, and keep the energy honest. If you're sweating and slightly out of breath, even better — that's the point.","format":"30s vertical, do-it-with-me","budget":22000,"tags":["On camera","Do-with-me","Beginner-friendly"],"loc":"Nigeria · Abuja"},
    {"old":"Fintech app explainer, talking to camera","title":"Explain sending money like you're teaching your mum — on camera","desc":"We'll pay well for one thing done properly: take ONE task in the app (send money, create a goal, pay a bill) and explain it so a first-timer gets it in under a minute. Talk to camera like you're walking your mum through it — patient, plain Nigerian English, no jargon, no feature list. If grandma would understand, you nailed it.","format":"45–60s talking-head + screen","budget":60000,"tags":["On camera","Screen share","Remote","Nigerian English"]},
    {"old":"Mobile app demo for a Nigerian product","title":"Show it working — one job, start to finish, no feature dump","desc":"Pick a single job the app does and walk it end to end: open, do, done. Face and screen both in frame so it feels like a person, not a tutorial channel. Plain language. If you hit a rough edge, leave it in — honest beats polished here.","format":"30–45s screen + face","budget":45000,"tags":["On camera","Screen share","Remote","Human only"]},
    {"old":"Day-in-the-life video with one product","title":"A real day, lightly branded — story first, product second","desc":"We don't want an ad, we want a day. String together a few real moments of yours and let the product appear once, naturally, where it actually fits. The story has to carry it; if the product feels bolted on, it didn't work. Your voice over it, calm and real.","format":"40–60s vertical, day-in-the-life","budget":26000,"tags":["On camera","Voiceover","Storytelling","Human only"],"loc":"Nigeria · Abuja"},
    {"old":"Unboxing video, first reaction on camera","title":"Open it on camera — we want the first face, not the fifth take","desc":"Press record BEFORE you open it. We want the genuine first reaction — the pause, the surprise, even the 'hmm.' One honest sentence about what you expected vs what you got. Don't re-shoot for a better reaction; the real one is the asset.","format":"20–40s vertical, one take","budget":20000,"tags":["On camera","Product ships","One take"]},
    {"old":"Honest product review, what you would tell a friend","title":"Review it like you owe us nothing — what's good AND what you'd change","desc":"A review that only praises is useless to us and obvious to everyone. Use it for a few days, then tell the camera what actually worked and the one thing you'd change. We will not reject you for a fair criticism — we'll trust the praise more because of it.","format":"45–60s vertical, to camera","budget":35000,"tags":["On camera","Product ships","Candid","One revision"],"slots":1},
    {"old":"Testimonial video about a product you use","title":"One specific moment it helped — name, face, and a real detail","desc":"Skip the slogans. Tell us the single moment the product actually did something for you — where you were, what happened, how it felt. Your real name and face. Specific beats glowing every time; a small true detail sells harder than a big vague claim.","format":"30–45s vertical testimonial","budget":30000,"tags":["On camera","Real name + face","Human only"]},
    {"old":"Short skit that sells one product","title":"Make us laugh in 30 seconds — and the product is the punchline","desc":"You're funny; prove it. Write a tiny scene with a setup and a turn where the product is the reason the scene flips. Perform it yourself. We'd rather one genuinely funny 25-second skit than a minute of trying. If it makes the edit team laugh, you're hired.","format":"25–35s skit, you perform","budget":40000,"tags":["On camera","Scripted","Comedy","You act"]},
    {"old":"Voice-over for a brand film","title":"Lend us your voice — warm, Nigerian, 60 seconds, we cut to picture","desc":"Remote and clean: record up to 60 seconds of warm, clear Nigerian-English voice-over to the script we send. No music bed from your side, no effects — just your voice, well-recorded, a couple of reads so we can choose. If your room echoes, throw a blanket up; we'll notice.","format":"Voice-over only, up to 60s","budget":18000,"tags":["Voice only","Remote","Nigerian English","Scripted"],"slots":1},
    {"old":"How-to tutorial, one skill in one minute","title":"Teach one thing a viewer can finish with you in a minute","desc":"One skill, start to finish, nothing extra. No montage of ten tips — pick ONE, put the steps on screen, stay in frame, and let the viewer finish it alongside you. If they can do it after watching once, it worked.","format":"60s vertical how-to","budget":24000,"tags":["On camera","On-screen steps","One revision"]},
    {"old":"Get-ready-with-me using one product","title":"Get ready like we're not watching — the product just happens to be there","desc":"Do your real getting-ready — the pace, the pauses, the talking-to-yourself — and let the product land where it naturally fits in your routine. Your room, your light, your voice. The less it feels performed, the more we want it.","format":"40–60s GRWM vertical","budget":27000,"tags":["On camera","Product ships","Natural light","Human only"],"loc":"Nigeria · Abuja"},
    {"old":"Gadget demo, show it working","title":"Say what it does in one sentence, then prove it with your hands","desc":"No spec sheet. Open on the one sentence that says what this device is for, then immediately show it doing that job in your hands — close, clear, real. One 'oh, nice' moment is worth more than a list of features. Lagos creators preferred so we can ship fast.","format":"30–45s demo, hands-on","budget":24000,"tags":["On camera","Product ships","Hands-on","Lagos preferred"]},
    {"old":"Event recap, what it felt like to be there","title":"Make someone who missed it feel the FOMO — a 90-second recap","desc":"Don't document the event, bottle the feeling of being in the room. The crowd, one face, one moment, and a last beat that makes someone who skipped it wish they hadn't. Shot on location in Lagos. Energy over coverage.","format":"60–90s vertical recap","budget":38000,"tags":["On location","On camera","Lagos","Fast turnaround"],"slots":1},
    {"old":"Travel-style brand clip in your city","title":"Film your city like you live there — because you do","desc":"Pick one spot in your city that means something and place the brand into that scene like it belongs. We want the feeling that a real local shot this, not a tourist with a brief. Let your place do the talking.","format":"30–45s vertical, on location","budget":28000,"tags":["On location","On camera","Cinematic","Human only"]},
    {"old":"Interview clip, one question answered well","title":"Answer one question like a host just asked you — a whole thought, not a quote card","desc":"We'll send one question. Answer it to camera as if someone across the table asked — a complete, considered thought with a beginning and an end. No quote-card energy, no rush. Remote is fine; a quiet room and clear sound is the whole job.","format":"30–45s talking-head","budget":25000,"tags":["On camera","Remote","Studio sound"]},
    {"old":"Dance or trend video with a product in it","title":"Ride the current trend — but don't stop dancing to explain the product","desc":"Use whatever's moving right now and keep the product visible without ever breaking the flow to pitch it. If you have to pause and explain, it's not working. The product should just be in the world of the video. Make it feel native to your feed.","format":"15–30s trend video","budget":20000,"tags":["On camera","Trend-led","No captions needed"]},
    {"old":"Story-first brand film, make someone feel it","title":"Open on a feeling, not a logo — one story people will repeat","desc":"This is the ambitious one and we're paying for it. Open on an emotion, not a product. Tell one small human story where the product matters quietly, and end on a line a viewer would actually repeat to someone. Take your time; make us feel something.","format":"45–75s vertical film","budget":120000,"tags":["On camera","Scripted","Premium","Music optional"],"slots":1},
    {"old":"Product reel for an e-commerce drop","title":"Shoot it like it's about to sell out — a drop reel with urgency","desc":"One product, clean light, a few strong angles, and one line on why to grab it before it's gone. Fast, crisp, made for a feed that scrolls. Lagos so we can courier the sample today. Think 'last three left,' not 'museum piece.'","format":"20–30s product reel","budget":22000,"tags":["Product ships","Studio-lit","Lagos","Fast turnaround"]},
    {"old":"Customer FAQ video, answer the top three questions","title":"Answer the three questions every buyer asks — no fluff between them","desc":"We'll give you the three questions buyers always ask. Answer them to camera, one after another, tight — a viewer should leave with zero doubts left. Plain and confident. Remote is fine. Brevity is the skill we're paying for.","format":"45–60s vertical FAQ","budget":28000,"tags":["On camera","Remote","Scripted","One revision"]},
    {"old":"Street interview clip, real reactions to a product","title":"Put it in strangers' hands on a Lagos street — keep the awkward reactions","desc":"Take it to the street and ask real people one question about it. Keep the honest reactions — the confused ones, the surprised ones, the 'I'd buy that' ones. Do NOT stage it. The awkwardness is the credibility; the polished version is worthless to us.","format":"45–60s street vox-pop","budget":42000,"tags":["On location","Candid","Unscripted","Lagos"]}
  ]$b$::jsonb) loop
    update public.briefs b set
      title = item->>'title',
      description = item->>'desc',
      format = item->>'format',
      budget_naira = (item->>'budget')::integer,
      tags = array(select jsonb_array_elements_text(item->'tags')),
      location = coalesce(item->>'loc', b.location),
      slots = coalesce((item->>'slots')::smallint, b.slots)
    where b.brand_id = brand and b.title = item->>'old';
  end loop;
end $$;
